import { createContext, useContext, useEffect, useState } from "react";

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [initData, setInitData] = useState("");


    useEffect(() => {
        const tg = window.Telegram.WebApp;
        tg.ready();

        // ۱. دریافت اطلاعات کاربر
        const userData = tg.initDataUnsafe.user;
        const userDataSafe = tg.initData;

        // ۲. ذخیره در Local Storage
        if (userData) {
            const userProfile = {
                id: userData.id,
                firstName: userData.first_name,
                lastName: userData.last_name || "",
                username: userData.username || "",
                photoUrl: userData.photo_url || "", // آدرس تصویر پروفایل
            };

            localStorage.setItem("user", JSON.stringify(userProfile));

            setUser(userProfile);

        }else{
            const userProfile = null;

            localStorage.setItem("user", userProfile);
            setUser(userProfile);
        }

        localStorage.setItem("initdata", userDataSafe);
        setInitData(userDataSafe)
    }, []);

    return (
        <AuthContext.Provider value={{ user, initData }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => useContext(AuthContext);