import React, { useState, useEffect } from "react";
import axios from "axios";
import Loading from "./Loading";
import ErrorPage from "./ErrorPage";

import { useAuth } from "../../context/AuthContext";

const AuthWrapper = ({ children }) => {
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const { initData } = useAuth();
    const sleep = (ms) => {
        return new Promise((resolve) => setTimeout(resolve, ms));
    };
    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await axios.post(
                    "https://vpn-api.cyclone.fun:82/login/validate",
                    {
                        initData:
                        initData,
                    },
                    {
                        headers: {
                            "Content-Type": "application/json",
                        },
                    }
                );

                if (response.data.code === 200 && response.data.status) {
                    setIsAuthenticated(true);
                    localStorage.setItem("token", response.data.user.AuthToken);
                    localStorage.setItem("user", JSON.stringify(response.data.user));

                } else {
                    setError(response.data.message || "خطایی رخ داده است.");
                    await sleep(3000);
                    setLoading(true);
                    fetchData();
                }
            } catch (err) {
                setError("خطایی در ارتباط با سرور رخ داده است.");
                await sleep(3000);
                setLoading(true);
                fetchData();
            } finally {
                setLoading(false);

            }
        };

        if (initData !== null && initData.length)
            fetchData();

    }, [initData]);


    if (loading) {
        return <Loading />;
    }

    // نمایش صفحه خطا در صورت وجود خطا
    if (error) {
        return <ErrorPage message={error} />;
    }

    // نمایش صفحات اصلی در صورت معتبر بودن کاربر
    return isAuthenticated ? children : <ErrorPage message="دسترسی غیرمجاز" />;
};

export default AuthWrapper;