import {
    Container,
    Box,
    Typography,
    Divider,
    List,
    ListItemAvatar,
    Avatar,
    Chip,
    Button,
    Card,
    CardContent,
    Dialog,
    DialogContent,
    DialogTitle,
    IconButton,
    CardHeader,
    RadioGroup,
    FormControlLabel,
    Radio,
} from "@mui/material";
import { useNavigate } from "react-router-dom";

import AccountBalanceWalletIcon from "@mui/icons-material/AccountBalanceWallet";
import { useTheme } from "@mui/material/styles";
import { useEffect, useState } from "react";
import { toJalaali, jalaaliToGregorian } from 'jalaali-js';

import CloseIcon from "@mui/icons-material/Close";
import {
    CreditCard as BankIcon, // آیکن کارت بانکی
    CurrencyBitcoin as CryptoIcon, // آیکن ارز دیجیتال
} from "@mui/icons-material";
import axios from "axios";

function convertTimestampToJalali(timestamp) {
    // تبدیل timestamp به تاریخ میلادی
    const date = new Date(timestamp * 1000); // ضرب در 1000 برای تبدیل به میلی‌ثانیه
    const year = date.getFullYear();
    const month = date.getMonth() + 1; // ماه‌ها در JavaScript از 0 شروع می‌شوند
    const day = date.getDate();

    // تبدیل تاریخ میلادی به تاریخ شمسی
    const jalaliDate = toJalaali(year, month, day);

    return `${jalaliDate.jy}/${jalaliDate.jm}/${jalaliDate.jd}`;
}

const TransactionItem = ({ transaction }) => {
    const theme = useTheme();

    return (
        <Card
            sx={{
                mb: 2,
                borderRadius: 3,
                boxShadow: "0 2px 8px rgba(0,0,0,0.05)",
                transition: "transform 0.2s",
                "&:hover": {
                    transform: "translateY(-2px)",
                    boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
                },
            }}
        >
            <CardContent sx={{ p: 2, display: "flex", alignItems: "center" }}>
                {/* آیکن وضعیت */}
                <ListItemAvatar>
                    <Avatar
                        sx={{
                            bgcolor:
                                transaction.ttype === "+"
                                    ? theme.palette.success.light
                                    : theme.palette.error.light,
                            width: 48,
                            height: 48,
                            fontSize: 24,
                        }}
                    >
                        {transaction.ttype === "+" ? "+" : "-"}
                    </Avatar>
                </ListItemAvatar>

                {/* اطلاعات تراکنش */}
                <Box sx={{ flexGrow: 1, mr: 2 }}>
                    <Typography variant="subtitle1" fontWeight="bold">
                        {transaction.title}
                    </Typography>
                    <Typography variant="body2" color="text.disabled">
                        {convertTimestampToJalali(transaction.ts)}
                    </Typography>
                </Box>

                {/* مبلغ و نوع تراکنش */}
                <Box textAlign="left">
                    <Typography
                        variant="h6"
                        color={transaction.ttype === "+" ? "success.main" : "error.main"}
                    >
                        {transaction.amount} تومان
                    </Typography>
                    <Chip
                        label={transaction.ttype === "+" ? "واریز" : "برداشت"}
                        size="small"
                        sx={{
                            mt: 1,
                            bgcolor:
                                transaction.ttype === "+"
                                    ? theme.palette.success.light
                                    : theme.palette.error.light,
                            color: "white",
                            borderRadius: 1,
                            fontSize: 12,
                        }}
                    />
                </Box>
            </CardContent>
        </Card>
    );
};

const PaymentDialog = ({ open, onClose }) => {
    const [selectedMethod, setSelectedMethod] = useState("");
    const theme = useTheme();
    const navigate = useNavigate();

    const handleSelect = (event) => {
        setSelectedMethod(event.target.value);
    };

    const handleSubmit = () => {
        if (selectedMethod === "card") {
            navigate("/wallet/increase/card");
        } else if (selectedMethod === "crypto") {
            navigate("/wallet/increase/crypto");
        }
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            fullWidth
            maxWidth="sm"
            PaperProps={{
                style: { borderRadius: 16, overflow: "hidden" },
            }}
        >
            <DialogTitle>
                <Box display="flex" justifyContent="space-between" alignItems="center">
                    <Typography variant="h6">انتخاب روش پرداخت</Typography>
                    <IconButton onClick={onClose}>
                        <CloseIcon />
                    </IconButton>
                </Box>
            </DialogTitle>
            <DialogContent>
                <RadioGroup
                    value={selectedMethod}
                    onChange={handleSelect}
                    sx={{ mt: 2 }}
                >
                    {/* روش کارت به کارت */}
                    <FormControlLabel
                        value="card"
                        control={<Radio />}
                        label={
                            <Card
                                sx={{
                                    p: 2,
                                    mb: 2,
                                    border: `2px solid ${
                                        selectedMethod === "card"
                                            ? theme.palette.primary.main
                                            : "transparent"
                                    }`,
                                    borderRadius: 2,
                                    transition: "border-color 0.3s",
                                }}
                            >
                                <CardHeader
                                    avatar={<BankIcon sx={{fontSize: 40, color: "primary.main" }} />}
                                    title="کارت به کارت"
                                    subheader="زمان واریز: حداقل نیم ساعت"
                                    titleTypographyProps={{ variant: "subtitle1" }}
                                    subheaderTypographyProps={{ variant: "caption" }}
                                    sx={{
                                        display: "flex",
                                        flexDirection: "row", // جابجایی آیکن به سمت راست
                                        justifyContent: "space-between", // فضای بین آیکن و نوشته‌ها
                                        alignItems: "center", // تنظیم عمودی عناصر
                                    }}
                                />
                            </Card>
                        }
                    />

                    {/* روش ارز دیجیتال */}
                    <FormControlLabel
                        value="crypto"
                        control={<Radio />}
                        label={
                            <Card
                                sx={{
                                    p: 2,
                                    border: `2px solid ${
                                        selectedMethod === "crypto"
                                            ? theme.palette.success.main
                                            : "transparent"
                                    }`,
                                    borderRadius: 2,
                                    transition: "border-color 0.3s",
                                }}
                            >
                                <CardHeader
                                    avatar={<CryptoIcon sx={{ fontSize: 40, color: "success.main" }} />}
                                    title="پرداخت با ارز دیجیتال"
                                    subheader="واریز آنی + 5% شارژ بیشتر"
                                    titleTypographyProps={{ variant: "subtitle1" }}
                                    subheaderTypographyProps={{ variant: "caption" }}
                                />
                            </Card>
                        }
                    />
                </RadioGroup>

                <Button
                    variant="contained"
                    fullWidth
                    onClick={handleSubmit}
                    disabled={!selectedMethod}
                    sx={{
                        mt: 3,
                        bgcolor: selectedMethod ? "primary.main" : "grey.300",
                        "&:disabled": { bgcolor: "grey.300" },
                    }}
                >
                    ادامه
                </Button>
            </DialogContent>
        </Dialog>
    );
};

const WalletPage = () => {
    const theme = useTheme();
    const [transactions, setTransactions] = useState([]);

    // اضافه کردن state برای دیالوگ
    const [paymentOpen, setPaymentOpen] = useState(false);

    const [walletPage, setWalletPage] = useState({
        balance: 0
    })


    useEffect(() => {
        try {
            let lsUser = JSON.parse(localStorage.getItem("user"));
            setWalletPage({
                balance: lsUser.wallet_balance
            });

            const fetchWallet = async () => {
                try {
                    const response = await axios.get(
                        "https://vpn-api.cyclone.fun:82/wallet/balance",
                        {
                            headers: {
                                "Content-Type": "application/json",
                                "Authorization": localStorage.getItem("token"),
                            },
                        }
                    );

                    if (response.data.code === 200 && response.data.status) {
                        setWalletPage({
                            balance: response.data.user.balance
                        });
                        fetchTransactions();
                    } else {
                        console.log(response.data.message || "خطایی رخ داده است.");
                    }
                } catch (err) {
                    console.log( "خطایی در ارتباط رخ داده است.");
                }
            };
            const fetchTransactions = async () => {
                try {
                    const response = await axios.get(
                        "https://vpn-api.cyclone.fun:82/wallet/txs",
                        {
                            headers: {
                                "Content-Type": "application/json",
                                "Authorization": localStorage.getItem("token"),
                            },
                        }
                    );

                    if (response.data.code === 200 && response.data.status) {
                        setTransactions(response.data.user.txs);
                    } else {
                        console.log(response.data.message || "خطایی رخ داده است.");
                    }
                } catch (err) {
                    console.log( "خطایی در ارتباط رخ داده است.");
                }
            }
            fetchWallet();

        }catch (e) {
            console.log(e);
        }

    }, [localStorage.getItem("user")]);


    return (
        <Container maxWidth="sm" sx={{ mt: 4 , mb:12}}>
            {/* بخش موجودی کیف پول */}
            <Box textAlign="center" mb={4}>
                <AccountBalanceWalletIcon
                    sx={{
                        fontSize: 64,
                        color: theme.palette.primary.main,
                        mb: 2,
                    }}
                />
                <Typography variant="h4" fontWeight="bold" color="primary">
                    {walletPage.balance} تومان
                </Typography>
                <Typography variant="body1" color="text.secondary">
                    موجودی قابل استفاده
                </Typography>
            </Box>

            <Divider sx={{ my: 3, opacity: 0.3 }} />


            <Button
                variant="contained"
                fullWidth
                endIcon={<AccountBalanceWalletIcon />}
                onClick={() => setPaymentOpen(true)}
                sx={{
                    mb: 4,
                    bgcolor: "success.main",
                    "&:hover": { bgcolor: "success.dark" },
                    borderRadius: 5,
                    py: 1.5,
                }}
            >
                افزایش موجودی
            </Button>

            {/* لیست تراکنش ها */}
            <Typography variant="h6" fontWeight="bold" mb={2}>
                تراکنش های اخیر
            </Typography>

            <List sx={{ p: 0 }}>
                {transactions.map((item) => (
                    <TransactionItem key={item.id} transaction={item} />
                ))}
            </List>

            <PaymentDialog
                open={paymentOpen}
                onClose={() => setPaymentOpen(false)}
            />
        </Container>
    );
};

export default WalletPage;