import {
    Container,
    Typography,
    Divider,
    Card,
    CardContent,
    Box,
    Select,
    MenuItem,
    FormControl,
    InputLabel,
    List,
    ListItem,
    ListItemAvatar,
    Avatar,
    ListItemText,
    Button,
    CircularProgress,
    useTheme,
    IconButton, Tooltip, Alert
} from "@mui/material";
import { CurrencyBitcoin, AccountBalanceWallet } from "@mui/icons-material";
import { useEffect, useState } from "react";
import axios from "axios";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import {toJalaali} from "jalaali-js";
function convertTimestampToJalali(timestamp) {
    // تبدیل timestamp به تاریخ میلادی
    const date = new Date(timestamp * 1000); // ضرب در 1000 برای تبدیل به میلی‌ثانیه
    const year = date.getFullYear();
    const month = date.getMonth() + 1; // ماه‌ها در JavaScript از 0 شروع می‌شوند
    const day = date.getDate();

    // تبدیل تاریخ میلادی به تاریخ شمسی
    const jalaliDate = toJalaali(year, month, day);

    return `${jalaliDate.jy}/${jalaliDate.jm}/${jalaliDate.jd}`;
}
const CryptoPaymentPage = () => {
    const theme = useTheme();
    const [network, setNetwork] = useState("");
    const [currency, setCurrency] = useState("");
    const [walletAddress, setWalletAddress] = useState("");
    const [walletMemo, setWalletMemo] = useState("");
    const [confirmationTime, setConfirmationTime] = useState("");
    const [transactions, setTransactions] = useState([]);
    const [loading, setLoading] = useState(false);


    const networkOptions = [
        /*{ value: "ethereum", label: "اتریوم", icon: `${process.env.PUBLIC_URL}/assets/networks/ethereum.png` },*/
        { value: "ton", label: "TON", icon: `${process.env.PUBLIC_URL}/assets/networks/ton.png` },
        /*{ value: "bsc", label: "BSC", icon: `${process.env.PUBLIC_URL}/assets/networks/bsc.png` },
        { value: "tron", label: "Tron", icon: `${process.env.PUBLIC_URL}/assets/networks/tron.png` },
        { value: "base", label: "Base", icon: `${process.env.PUBLIC_URL}/assets/networks/base.png` },
        { value: "sol", label: "Solana", icon: `${process.env.PUBLIC_URL}/assets/networks/sol.png` },*/
    ];
    const currencyOptions = {
        /*ethereum: [
            { value: "eth", label: "اتریوم", icon: `${process.env.PUBLIC_URL}/assets/currencies/eth.png` },
            { value: "usdt", label: "تتر", icon: `${process.env.PUBLIC_URL}/assets/currencies/usdt.png` },
        ],*/
        ton: [
            { value: "ton", label: "TON", icon: `${process.env.PUBLIC_URL}/assets/currencies/ton.png` },
            /*{ value: "usdt", label: "تتر", icon: `${process.env.PUBLIC_URL}/assets/currencies/usdt.png` },*/
        ],
        /*bsc: [
            { value: "bnb", label: "BNB", icon: `${process.env.PUBLIC_URL}/assets/currencies/bnb.png` },
            { value: "dai", label: "DAI", icon: `${process.env.PUBLIC_URL}/assets/currencies/dai.png` },
        ],
        tron: [
            { value: "trx", label: "TRX", icon: `${process.env.PUBLIC_URL}/assets/currencies/trx.png` },
            { value: "usdt", label: "تتر", icon: `${process.env.PUBLIC_URL}/assets/currencies/usdt.png` },
        ],
        base: [
            { value: "eth", label: "اتریوم", icon: `${process.env.PUBLIC_URL}/assets/currencies/eth.png` },
            { value: "usdc", label: "USDC", icon: `${process.env.PUBLIC_URL}/assets/currencies/usdc.png` },
        ],
        sol: [
            { value: "sol", label: "Solana", icon: "/assets/currencies/sol.png" },
            { value: "usdt", label: "تتر", icon: "/assets/currencies/usdt.png" },
        ],*/
    };
    const networkTimes = {
        ethereum: "2 دقیقه",
        ton: "30 ثانیه",
        bsc: "1 دقیقه",
        tron: "45 ثانیه",
        base: "1 دقیقه",
        sol: "30 ثانیه",
    };
    const handleCopyWalletAddress = () => {
        navigator.clipboard.writeText(walletAddress).then(() => {
            alert("آدرس کیف پول کپی شد!");
        });
    };
    const handleCopyMemoValue = () => {
        navigator.clipboard.writeText(walletMemo).then(() => {
            alert("ممو کپی شد!");
        });
    };



    useEffect(() => {
        const fetchAddress = async () => {
            let URL_path = "";
            switch (network) {
                case "ethereum":
                    URL_path = "eth";
                    break;
                case "ton":
                    URL_path = "ton";
                    break;
            }
            try {
                const response = await axios.get(
                    `https://vpn-api.cyclone.fun:82/wallet/crypto/${URL_path}/address`,
                    {
                        headers: {
                            "Content-Type": "application/json",
                            "Authorization": localStorage.getItem("token"),
                        },
                    }
                );

                if (response.data.code === 200 && response.data.status) {

                    switch (network){
                        case "ton":
                            setWalletAddress(response.data.wallet.address.public_address);
                            setWalletMemo(response.data.wallet.address.comment);
                            break;
                        default:
                            setWalletAddress(response.data.wallet.address);
                            setWalletMemo("");
                    }

                    setConfirmationTime(networkTimes[network]);
                } else {
                    setWalletAddress(response.data.message || "خطایی رخ داده است.");
                    setConfirmationTime("آدرس کیف پول دریافت نشد!");
                }
            } catch (err) {
                setWalletAddress( "خطایی در ارتباط رخ داده است.");
                setConfirmationTime("آدرس کیف پول دریافت نشد!");
            }
        };
        if (network && currency)
            fetchAddress();
    }, [network, currency]);

    useEffect(() => {
        const fetchtxs = async () => {
            let URL_path = "";
            switch (network) {
                case "ton":
                    URL_path = "ton";
                    break;
            }
            try {
                const response = await axios.get(
                    `https://vpn-api.cyclone.fun:82/wallet/crypto/${URL_path}/txs`,
                    {
                        headers: {
                            "Content-Type": "application/json",
                            "Authorization": localStorage.getItem("token"),
                        },
                    }
                );
                if (response.data.code === 200 && response.data.status) {
                    setTransactions(response.data.txs)
                } else {
                    console.log("err")
                }
            } catch (err) {
                console.log(err)
            }
        };
        const fetchAlltxs = async () => {
            try {
                const response = await axios.get(
                    `https://vpn-api.cyclone.fun:82/wallet/crypto/txs`,
                    {
                        headers: {
                            "Content-Type": "application/json",
                            "Authorization": localStorage.getItem("token"),
                        },
                    }
                );
                if (response.data.code === 200 && response.data.status) {
                    setTransactions(response.data.txs)
                } else {
                    console.log("err")
                }
            } catch (err) {
                console.log(err)
            }
        };
        if (network && currency)
            fetchtxs();
        else
            fetchAlltxs();


    }, [network, currency]);

    const handleRefresh = () => {
        setLoading(true);
        setTransactions([]);

        const fetchtxs = async () => {
            let URL_path = "";
            switch (network) {
                case "ton":
                    URL_path = "ton";
                    break;
            }
            try {
                const response = await axios.get(
                    `https://vpn-api.cyclone.fun:82/wallet/crypto/${URL_path}/txs`,
                    {
                        headers: {
                            "Content-Type": "application/json",
                            "Authorization": localStorage.getItem("token"),
                        },
                    }
                );
                if (response.data.code === 200 && response.data.status) {
                    setLoading(false);
                    setTransactions(response.data.txs)
                } else {
                    setLoading(false);
                    console.log("err")
                }
            } catch (err) {
                setLoading(false);
                console.log(err)
            }
        };
        fetchtxs();
    };

    return (
        <Container maxWidth="sm" sx={{ mt: 4 , mb:12}}>
            {/* بخش بالای صفحه */}
            <Box textAlign="center" mb={4}>
                <CurrencyBitcoin sx={{ fontSize: 64, color: "success.main" }} />
                <Typography variant="h5" fontWeight="bold" color="success.main">
                    واریز با ارزدیجیتال
                </Typography>
                <Typography variant="body1" color="text.secondary">
                    واریزیهای ارزدیجیتال شامل 5% شارژ هدیه میباشند
                </Typography>
            </Box>

            <Divider sx={{ my: 3, opacity: 0.3 }} />

            {/* کارت انتخاب شبکه و ارز */}
            <Card sx={{ mb: 4, borderRadius: 3, boxShadow: 2 }}>
                <CardContent>
                    {/* انتخاب شبکه */}
                    <FormControl fullWidth sx={{ mb: 3 }}>
                        <InputLabel>انتخاب شبکه</InputLabel>
                        <Select
                            value={network}
                            label="انتخاب شبکه"
                            onChange={(e) => {
                                setNetwork(e.target.value);
                                setCurrency("");
                            }}
                            startAdornment={
                                network && (
                                    <img
                                        src={networkOptions.find((n) => n.value === network)?.icon}
                                        alt="network"
                                        style={{ width: 24, marginRight: 10 }}
                                    />
                                )
                            }
                        >
                            {networkOptions.map((option) => (
                                <MenuItem key={option.value} value={option.value}>
                                    <img
                                        src={option.icon}
                                        alt={option.label}
                                        style={{ width: 24, marginRight: 10 }}
                                    />
                                    {option.label}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>

                    {/* انتخاب ارز */}
                    {network && (
                        <FormControl fullWidth>
                            <InputLabel>انتخاب ارز</InputLabel>
                            <Select
                                value={currency}
                                label="انتخاب ارز"
                                onChange={(e) => setCurrency(e.target.value)}
                                startAdornment={
                                    currency && (
                                        <img
                                            src={
                                                currencyOptions[network].find(
                                                    (c) => c.value === currency
                                                )?.icon
                                            }
                                            alt="currency"
                                            style={{ width: 24, marginRight: 10 }}
                                        />
                                    )
                                }
                            >
                                {currencyOptions[network].map((option) => (
                                    <MenuItem key={option.value} value={option.value}>
                                        <img
                                            src={option.icon}
                                            alt={option.label}
                                            style={{ width: 24, marginRight: 10 }}
                                        />
                                        {option.label}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    )}
                </CardContent>
            </Card>

            {/* نمایش آدرس کیف پول */}
            {walletAddress && (
                <Card sx={{ mb: 4, p: 2, borderRadius: 2 }}>
                    {/* متن هشدار */}
                    <Alert severity="warning" sx={{ mb: 2, mr: 2 }}>
                        واریز رمز ارز اشتباه به این آدرس باعث از دست رفتن دارایی شما می‌شود. لطفاً در واریز نهایت دقت را کنید.
                    </Alert>

                    {/* آدرس کیف پول */}
                    <Typography variant="subtitle1" gutterBottom>
                        آدرس کیف پول:
                    </Typography>
                    <div
                        style={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "space-between",
                            bgcolor: "background.default",
                            p: 2,
                            borderRadius: 1,
                        }}
                    >
                        <Typography
                            variant="caption"
                            sx={{
                                overflow: "hidden",
                                textOverflow: "ellipsis",
                                whiteSpace: "nowrap",
                                maxWidth: "calc(100% - 40px)", // فضای کافی برای دکمه کپی
                            }}
                        >
                            {walletAddress}
                        </Typography>
                        <Tooltip title="کپی آدرس">
                            <IconButton onClick={handleCopyWalletAddress} size="small">
                                <ContentCopyIcon fontSize="small" />
                            </IconButton>
                        </Tooltip>
                    </div>

                    {/* ممو (شبکه تون) */}
                    {walletMemo && (
                        <div>
                        <Typography variant="subtitle1" gutterBottom>
                            ممو (کامنت):
                        </Typography>
                        <div
                        style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                        bgcolor: "background.default",
                        p: 2,
                        borderRadius: 1,
                    }}
                >
                    <Typography
                        variant="caption"
                        sx={{
                            overflow: "hidden",
                            textOverflow: "ellipsis",
                            whiteSpace: "nowrap",
                            maxWidth: "calc(100% - 40px)", // فضای کافی برای دکمه کپی
                        }}
                    >
                        {walletMemo}
                    </Typography>
                    <Tooltip title="کپی ممو">
                        <IconButton onClick={handleCopyMemoValue} size="small">
                            <ContentCopyIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                </div>
                        </div>
                    )}






                    {/* زمان تایید تراکنش */}
                    <Typography variant="caption" color="text.secondary">
                        زمان تایید تراکنش: {confirmationTime}
                    </Typography>
                </Card>
            )}
            {/* دکمه بروزرسانی */}
            <Button
                variant="outlined"
                fullWidth
                startIcon={
                    loading ? (
                        <CircularProgress size={24} color="inherit" />
                    ) : (
                        <AccountBalanceWallet />
                    )
                }
                onClick={handleRefresh}
                disabled={loading}
                sx={{ mt: 0, mb: 4, py: 1.5, borderRadius: 5 }}
            >
                {loading ? "در حال بروزرسانی..." : "بررسی واریزی جدید"}
            </Button>

            {/* لیست واریزهای اخیر */}
            <Typography variant="h6" fontWeight="bold" mb={2} textAlign="right">
                تراکنش های اخیر
            </Typography>
            <List>
                {transactions.map((tx) => (
                    <ListItem key={tx.id}>
                        <ListItemAvatar>
                            <Avatar
                                src={`${process.env.PUBLIC_URL}/assets/networks/${tx.network.toLowerCase()}.png`}
                                alt={tx.network}
                            />
                        </ListItemAvatar>
                        <ListItemText
                            primary={`(${tx.currency.toUpperCase()}) ${tx.amount.currency}  `}
                            secondary={`${convertTimestampToJalali(tx.find_ts)}`}
                        />
                    </ListItem>
                ))}
            </List>


        </Container>
    );
};

export default CryptoPaymentPage;