import React, { useState, useEffect } from 'react';
import {
    Container,
    Typography,
    Grid,
    Button,
    MenuItem,
    Select,
    FormControl,
    InputLabel,
    Card,
    CardContent,
    Stack,
    Divider,
    Box,
    Alert,
    Skeleton,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Snackbar,
    useTheme,
    useMediaQuery,
} from '@mui/material';
import {
    Store,
    AccessTime as AccessTimeIcon,
    Storage as StorageIcon,
    AttachMoney as AttachMoneyIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import axios from "axios";




const FeatureItem = ({ icon, text }) => (
    <Stack
        direction="column"
        spacing={0}
        alignItems="center"
        sx={{
            flex: 1,
            justifyContent: 'center',
            py: 2,
            transition: 'all 0.3s',
            '&:hover': {
                backgroundColor: 'action.hover',
                borderRadius: 2,
            }
        }}
    >
        <Box
            sx={{
                bgcolor: 'primary.light',
                borderRadius: '50%',
                p: 1,
                width: 18,
                height: 18,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                mb:1,
            }}
        >
            {icon}
        </Box>
        <Typography variant="body1" color="text.secondary" sx={{ fontWeight: 500 }}>
            {text}
        </Typography>
    </Stack>
);

const PurchasePage = () => {
    const theme = useTheme();
    const navigate = useNavigate();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const [services, setServices] = useState([])
    const [loading, setLoading] = useState(true);



    const [walletBalance, setWalletBalance] = useState(0);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedService, setSelectedService] = useState(null);
    const [snackbarOpen, setSnackbarOpen] = useState({status:false,msg:""});



    useEffect(() => {
        const timer = setTimeout(() => setLoading(false), 500);
        return () => clearTimeout(timer);
    }, []);


    useEffect(() => {
        const fetchWallet = async () => {
            try {
                const response = await axios.get(
                    "https://vpn-api.cyclone.fun:82/wallet/balance",
                    {
                        headers: {
                            "Content-Type": "application/json",
                            "Authorization": localStorage.getItem("token"),
                        },
                    }
                );

                if (response.data.code === 200 && response.data.status) {
                    setWalletBalance(response.data.user.balance);
                } else {
                    setWalletBalance(0)
                    setSnackbarOpen({status:true,msg:response.data.message || "خطایی در دریافت موجودی رخ داد. "})
                }
            } catch (err) {
                setWalletBalance(0)
                setSnackbarOpen({status:true,msg:"خطایی در ارتباط رخ داده است."})
            }
        };
        fetchWallet();
    }, [isModalOpen]);



    const handlePurchaseClick = (service) => {
        setSelectedService(service);
        setIsModalOpen(true);
    };

    const handleConfirmPurchase = async () => {

        const serviceId = selectedService.id;

        try {
            const response = await axios.post(
                "https://vpn-api.cyclone.fun:82/services/BuyService",
                {
                    service_id:
                    serviceId,
                },
                {
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": localStorage.getItem("token"),
                    },
                }
            );

            if (response.data.code === 200 && response.data.status) {
                setIsModalOpen(false);
                setSnackbarOpen({status:true, msg:response.data.message});

            } else {
                setSnackbarOpen({status:true, msg:response.data.message || "خطایی رخ داده است."});
            }
        } catch (err) {
            setIsModalOpen(false);
            setSnackbarOpen({status:true, msg:"خطایی در ارتباط با سرور رخ داده است."});
        }
    };

    const handleAddBalance = () => {
        navigate('/wallet');
    };

    useEffect(() => {
        try {

            const fetchServices = async () => {
                try {
                    const response = await axios.get(
                        "https://vpn-api.cyclone.fun:82/services/servicesList",
                        {
                            headers: {
                                "Content-Type": "application/json",
                                "Authorization": localStorage.getItem("token"),
                            },
                        }
                    );

                    if (response.data.code === 200 && response.data.status) {
                        setServices(response.data.services);
                        setLoading(false);
                    } else {
                        console.log(response.data.message || "خطایی رخ داده است.");
                    }
                } catch (err) {
                    console.log( "خطایی در ارتباط رخ داده است.");
                }
            };

            fetchServices();

        }catch (e) {
            console.log(e);
        }
    }, []);

    return (
        <Container maxWidth="sm" sx={{ mt: 4 , mb:13}}>
            {/* هدر مطابق صفحه سرویس های من */}
            <Box textAlign="center" mb={4}>
                <Store sx={{ fontSize: 64, color: "primary.main" }} />
                <Typography variant="h5" fontWeight="bold" color="primary.main">
                    فروشگاه سرویس ها
                </Typography>
            </Box>
            <Divider sx={{ my: 3, opacity: 0.3 }} />




            {/* لیست سرویس ها */}
            {loading ? (
                <Grid container spacing={3}>
                    {[...Array(3)].map((_, index) => (
                        <Grid item xs={12} sm={6} md={4} key={index}>
                            <Card sx={{ borderRadius: 3 }}>
                                <CardContent>
                                    <Skeleton variant="rectangular" height={120} />
                                    <Skeleton variant="text" height={40} />
                                    <Skeleton variant="text" height={30} />
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                </Grid>
            ) : (
                <Grid container spacing={3}>
                    {services.length === 0 ? (
                        <Grid item xs={12}>
                            <Alert severity="info" sx={{ mt: 3 }}>
                                سرویسی با این مشخصات یافت نشد!
                            </Alert>
                        </Grid>
                    ) : (
                        services.map((service) => (
                            <Grid item xs={12} sm={6} md={4} key={service.id}>
                                <Card
                                    elevation={3}
                                    sx={{
                                        borderRadius: 4,
                                        transition: 'transform 0.3s, box-shadow 0.3s',
                                        '&:hover': {
                                            transform: 'translateY(-5px)',
                                            boxShadow: theme.shadows[10],
                                        },
                                    }}
                                >
                                    <CardContent sx={{ pb: 0 }}>
                                        {/* هدر کارت با دکمه خرید */}
                                        <Stack
                                            direction="row"
                                            justifyContent="space-between"
                                            alignItems="center"
                                            sx={{ mb: 2 }}
                                        >
                                            <Typography
                                                variant="h6"
                                                sx={{
                                                    fontWeight: 600,
                                                    color: 'primary.dark',
                                                }}
                                            >
                                                {service.title}
                                            </Typography>

                                            <Button
                                                variant="contained"
                                                color="success"
                                                size="small"
                                                onClick={() => handlePurchaseClick(service)}
                                                sx={{
                                                    borderRadius: 20,
                                                    py: 1,
                                                    transition: 'all 0.3s',
                                                    '&:hover': {
                                                        transform: 'scale(1.05)',
                                                        boxShadow: theme.shadows[4],
                                                    },
                                                }}
                                            >
                                                خرید سرویس
                                            </Button>
                                        </Stack>

                                        <Divider sx={{ mb: 3 }} />

                                        {/* مشخصات سرویس در یک ردیف */}
                                        <Stack
                                            direction="row"
                                            divider={<Divider orientation="vertical" flexItem />}
                                            spacing={2}
                                            sx={{ mt: 3 }}
                                        >
                                            {(service.duration/60/60/24) >= 30 ?
                                                (<FeatureItem icon={<AccessTimeIcon />} text={`${(service.duration/60/60/24/30) } ماه`} />)
                                                :
                                                (<FeatureItem icon={<AccessTimeIcon />} text={`${(service.duration/60/60/24) } روز`} />)
                                            }
                                            <FeatureItem icon={<StorageIcon />} text={`${service.traffic} گیگ`} />
                                            <FeatureItem icon={<AttachMoneyIcon />} text={`${service.price} تومان`} />
                                        </Stack>
                                    </CardContent>
                                </Card>
                            </Grid>
                        ))
                    )}
                </Grid>
            )}

            {/* مدال تایید خرید */}
            <Dialog
                open={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                fullWidth
                maxWidth="sm"
                PaperProps={{
                    sx: {
                        borderRadius: 4,
                        p: 3,
                    },
                }}
            >
                <DialogTitle>
                    <Typography variant="h5" component="h2" sx={{ fontWeight: 600 }}>
                        تایید خرید سرویس
                    </Typography>
                </DialogTitle>
                <DialogContent>
                    {selectedService && (
                        <Stack spacing={3}>
                            {/* مشخصات سرویس */}
                            <Stack spacing={0}>
                                <Typography variant="subtitle1" color="text.secondary">
                                    نام سرویس:
                                </Typography>
                                <Typography variant="body1">{selectedService.title}</Typography>
                            </Stack>
                            <Stack spacing={0}>
                                <Typography variant="subtitle1" color="text.secondary">
                                    لوکیشن:
                                </Typography>
                                <Typography variant="body1">{selectedService.location}</Typography>
                            </Stack>

                            <Stack spacing={0}>
                                <Typography variant="subtitle1" color="text.secondary">
                                    مدت زمان:
                                </Typography>
                                {(selectedService.duration/60/60/24) >= 30 ?
                                    (<Typography variant="body1">{`${(selectedService.duration/60/60/24/30) } ماه`}</Typography>)
                                    :
                                    (<Typography variant="body1">{`${(selectedService.duration/60/60/24) } روز`}</Typography>)
                                }
                            </Stack>

                            <Stack spacing={0}>
                                <Typography variant="subtitle1" color="text.secondary">
                                    حجم:
                                </Typography>
                                <Typography variant="body1">{selectedService.traffic} گیگ</Typography>
                            </Stack>

                            <Stack spacing={0}>
                                <Typography variant="subtitle1" color="text.secondary">
                                    قیمت:
                                </Typography>
                                <Typography variant="body1" sx={{ fontWeight: 600 }}>
                                    {selectedService.price} تومان
                                </Typography>
                            </Stack>

                            {/* موجودی کیف پول */}
                            <Stack spacing={0}>
                                <Typography variant="subtitle1" color="text.secondary">
                                    موجودی کیف پول:
                                </Typography>
                                <Typography variant="body1" sx={{ fontWeight: 600, color: 'success.main' }}>
                                    {walletBalance.toLocaleString()} تومان
                                </Typography>
                            </Stack>
                        </Stack>
                    )}
                </DialogContent>
                <DialogActions sx={{ mt: 3 }}>
                    {/* دکمه های عملیاتی */}
                    {selectedService && (
                        <>
                            <Button
                                variant="outlined"
                                color="primary"
                                fullWidth={isMobile}
                                onClick={() => setIsModalOpen(false)}
                                sx={{ mr: isMobile ? 0 : 2 , ml:isMobile ? 3 : 2}}
                            >
                                انصراف
                            </Button>

                            {parseInt(selectedService.price) <= walletBalance ? (
                                <Button
                                    variant="contained"
                                    color="success"
                                    fullWidth={isMobile}
                                    onClick={handleConfirmPurchase}
                                >
                                    خرید و فعالسازی
                                </Button>
                            ) : (
                                <Button
                                    variant="contained"
                                    color="warning"
                                    fullWidth={isMobile}
                                    onClick={handleAddBalance}
                                >
                                    افزایش موجودی
                                </Button>
                            )}
                        </>
                    )}
                </DialogActions>
            </Dialog>

            {/* اسنکبار موفقیت */}
            <Snackbar
                open={snackbarOpen.status}
                autoHideDuration={6000}
                onClose={() => setSnackbarOpen({status:false,msg:""})}
                message={snackbarOpen.msg}
                action={
                    <Button color="inherit" size="small" onClick={() => setSnackbarOpen(false)}>
                        بستن
                    </Button>
                }
            />
        </Container>
    );
};

export default PurchasePage;