import {
    Container,
    Typography,
    List,
    ListItem,
    ListItemAvatar,
    Avatar,
    ListItemText,
    Dialog,
    DialogTitle,
    DialogContent,
    Box,
    Button,
    IconButton,
    Tooltip,
    Chip,
    useTheme,
    Divider,
    LinearProgress
} from "@mui/material";
import { Storage, Public, Update, ContentCopy } from "@mui/icons-material";
import { useEffect, useState } from "react";
import CountryFlag from 'react-country-flag';
import axios from "axios";

const ServicesPage = () => {
    const theme = useTheme();
    const [services, setServices] = useState([]);
    const [selectedService, setSelectedService] = useState(null);

    useEffect(() => {

        const fetchMyServices = async () => {
            try {
                const response = await axios.get(
                    "https://vpn-api.cyclone.fun:82/services/myServices",
                    {
                        headers: {
                            "Content-Type": "application/json",
                            "Authorization": localStorage.getItem("token"),
                        },
                    }
                );

                if (response.data.code === 200 && response.data.status) {
                    setServices(response.data.services);
                } else {
                    console.log(response.data.message || "خطایی رخ داده است.");
                }
            } catch (err) {
                console.log( "خطایی در ارتباط رخ داده است.");
            }
        };
        fetchMyServices();
    }, []);



    const getVolumeProgress = (used, remaining, total) => {
        return used / total * 100;
    };

    const getTimeProgress = (duration, timeLeft) => {
        const totalDays = (duration);
        const remainingDays = (timeLeft);
        return ((totalDays - remainingDays) / totalDays) * 100;
    };

    const handleClose = () => setSelectedService(null);

    const handleCopyConfig = (config) => {
        navigator.clipboard.writeText(config);
        alert("کانفیگ با موفقیت کپی شد!");
    };

    return (
        <Container maxWidth="sm" sx={{ mt: 4 , mb:13}}>
            <Box textAlign="center" mb={4}>
                <Storage sx={{ fontSize: 64, color: "primary.main" }} />
                <Typography variant="h5" fontWeight="bold" color="primary.main">
                    سرویس های من
                </Typography>
            </Box>
            <Divider sx={{ my: 3, opacity: 0.3 }} />

            <List>
                {services.map((service) => (
                    <ListItem
                        key={service.id}
                        button
                        onClick={() => setSelectedService(service)}
                        sx={{
                            bgcolor: "background.paper",
                            mb: 2,
                            borderRadius: 2,
                            p: 2,
                            boxShadow: 1,
                            transition: "transform 0.2s",
                            "&:hover": { transform: "translateY(-2px)" },
                        }}
                    >
                        <ListItemAvatar>
                            <Avatar sx={{ width: 48, height: 48 }}>
                                {service.location === "Multi" ? (
                                    <Public />
                                ) : (
                                    <CountryFlag
                                        countryCode={service.location}
                                        svg
                                        style={{
                                            width: '100%',
                                            height: '100%',
                                            borderRadius: '50%'
                                        }}
                                    />
                                )}
                            </Avatar>
                        </ListItemAvatar>
                        <ListItemText
                            primary={
                                <Box display="flex" justifyContent="space-between">
                                    <Typography variant="subtitle1">
                                        {service.title}
                                    </Typography>
                                    <Chip
                                        label={service.status === 1 ? "فعال" : "منقضی شده"}
                                        color={service.status === 1 ? "success" : "error"}
                                        size="small"
                                    />
                                </Box>
                            }
                            secondary={
                                <Box>
                                    {/* نمایش پیشرفت حجم */}
                                    <Box mt={1}>
                                        <Typography variant="caption" color="text.secondary">
                                            مصرف حجم:
                                        </Typography>
                                        <Box sx={{ display: 'flex', alignItems: 'center', mt: 1 }}>
                                            <LinearProgress
                                                variant="determinate"
                                                value={getVolumeProgress(service.used_traffic, (service.all_traffic - service.used_traffic), service.all_traffic)}
                                                sx={{
                                                    height: 8,
                                                    flexGrow: 1,
                                                    mr: 1,
                                                    borderRadius: 2,
                                                    bgcolor: theme.palette.grey[200],
                                                    '& .MuiLinearProgress-bar': {
                                                        bgcolor: theme.palette.primary.main,
                                                    },
                                                }}
                                            />
                                            <Typography variant="caption" color="text.secondary">
                                                {`${service.used_traffic}GB/${service.all_traffic}`}
                                            </Typography>
                                        </Box>
                                    </Box>

                                    {/* نمایش پیشرفت زمان */}
                                    <Box mt={1}>
                                        <Typography variant="caption" color="text.secondary">
                                            زمان باقیمانده:
                                        </Typography>
                                        <Box sx={{ display: 'flex', alignItems: 'center', mt: 1 }}>
                                            <LinearProgress
                                                variant="determinate"
                                                value={getTimeProgress(service.duration, service.timeLeft)}
                                                sx={{
                                                    height: 8,
                                                    flexGrow: 1,
                                                    mr: 1,
                                                    borderRadius: 2,
                                                    bgcolor: theme.palette.grey[200],
                                                    '& .MuiLinearProgress-bar': {
                                                        bgcolor: theme.palette.secondary.main,
                                                    },
                                                }}
                                            />
                                            <Typography variant="caption" color="text.secondary">
                                                {`${service.timeLeft} روز باقیمانده`}
                                            </Typography>
                                        </Box>
                                    </Box>
                                </Box>
                            }
                        />
                    </ListItem>
                ))}
            </List>

            {/* دیالوگ جزئیات سرویس */}
            <Dialog
                open={!!selectedService}
                onClose={handleClose}
                fullWidth
                maxWidth="sm"
                PaperProps={{ style: { borderRadius: 16 } }}
            >
                <DialogTitle>
                    <Box display="flex" justifyContent="space-between" alignItems="center">
                        <Typography variant="h6">جزئیات سرویس</Typography>
                        <IconButton onClick={handleClose}>
                            <Tooltip title="بستن">
                                <span>×</span>
                            </Tooltip>
                        </IconButton>
                    </Box>
                </DialogTitle>
                <DialogContent>
                    {selectedService && (
                        <>
                            <Box display="flex" justifyContent="space-between" mb={3}>
                                <Box>
                                    <Typography variant="h5" fontWeight="bold">
                                        {selectedService.title}
                                    </Typography>
                                </Box>
                                <Avatar sx={{ width: 64, height: 64 }}>
                                    {selectedService.location === "Multi" ? (
                                        <Public />
                                    ) : (
                                        <CountryFlag
                                            countryCode={selectedService.location}
                                            svg
                                            style={{ width: '100%', height: '100%' }}
                                        />
                                    )}
                                </Avatar>
                            </Box>

                            {/* آمار پیشرفت حجم */}
                            <Box mb={3}>
                                <Typography variant="subtitle1" fontWeight="bold">
                                    مصرف حجم:
                                </Typography>
                                <Box sx={{ display: 'flex', alignItems: 'center', mt: 1 }}>
                                    <LinearProgress
                                        variant="determinate"
                                        value={getVolumeProgress(selectedService.used_traffic, (selectedService.all_traffic-selectedService.used_traffic), selectedService.all_traffic)}
                                        sx={{
                                            height: 12,
                                            flexGrow: 1,
                                            mr: 2,
                                            borderRadius: 4,
                                            bgcolor: theme.palette.grey[200],
                                            '& .MuiLinearProgress-bar': {
                                                bgcolor: theme.palette.primary.main,
                                            },
                                        }}
                                    />
                                    <Typography variant="body1">
                                        {`${selectedService.used_traffic}GB/${selectedService.all_traffic}`}
                                    </Typography>
                                </Box>
                            </Box>

                            {/* آمار پیشرفت زمان */}
                            <Box mb={3}>
                                <Typography variant="subtitle1" fontWeight="bold">
                                    زمان باقیمانده:
                                </Typography>
                                <Box sx={{ display: 'flex', alignItems: 'center', mt: 1 }}>
                                    <LinearProgress
                                        variant="determinate"
                                        value={getTimeProgress(selectedService.duration, selectedService.timeLeft)}
                                        sx={{
                                            height: 12,
                                            flexGrow: 1,
                                            mr: 2,
                                            borderRadius: 4,
                                            bgcolor: theme.palette.grey[200],
                                            '& .MuiLinearProgress-bar': {
                                                bgcolor: theme.palette.secondary.main,
                                            },
                                        }}
                                    />
                                    <Typography variant="body1">
                                        {`${selectedService.timeLeft} روز باقیمانده`}
                                    </Typography>
                                </Box>
                            </Box>



                            {/* دکمه های عملیاتی */}
                            <Box display="flex" gap={2}>
                                <Button
                                    variant="contained"
                                    startIcon={<ContentCopy />}
                                    onClick={() => handleCopyConfig(selectedService.config)}
                                    fullWidth
                                >
                                    کپی کانفیگ
                                </Button>
                                <Button
                                    variant="outlined"
                                    startIcon={<Update />}
                                    href={selectedService.updateLink}
                                    target="_blank"
                                    fullWidth
                                >
                                    آپدیت خودکار
                                </Button>
                            </Box>
                        </>
                    )}
                </DialogContent>
            </Dialog>
        </Container>
    );
};

export default ServicesPage;